const req = $input.first().json;
const body = req.body || {};
const payload = {};
if (typeof body.url === 'string' && body.url.trim()) {
  payload.url = body.url.trim();
}
if (Array.isArray(body.urls)) {
  const cleaned = body.urls.filter(v => typeof v === 'string' && v.trim()).map(v => v.trim());
  if (cleaned.length) payload.urls = cleaned;
}
if (!payload.url && !payload.urls) {
  return [{ json: { _status: 400, _body: { error: 'Request body must contain url or urls' } } }];
}
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://109.123.230.100:8787/process',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 'Bearer douyin-knowledge-service-token-20260330'
    },
    body: JSON.stringify(payload)
  });
  const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
  return [{ json: { _status: 200, _body: data } }];
} catch (e) {
  let details = null;
  if (e.response && e.response.body) {
    details = e.response.body;
  }
  return [{ json: { _status: 500, _body: { error: e.message, details } } }];
}
